solution.solution.cpp:
#include <algorithm>
#include <set>
#include <vector>

class Selection
{
public:
    void click(const std::vector<int>& rows, int id, bool ctrl, bool shift)
    {
        const auto a{ std::find(rows.begin(), rows.end(), m_anchor) };
        const auto b{ std::find(rows.begin(), rows.end(), id) };
        if (shift && m_anchor != -1 && a != rows.end() && b != rows.end())
        {
            if (!ctrl) m_selected.clear();
            auto from{ a }, to{ b };
            if (from > to) std::swap(from, to);
            for (auto it{ from }; it <= to; ++it) m_selected.insert(*it);
            return;
        }
        if (ctrl)
        {
            if (!m_selected.erase(id)) m_selected.insert(id);
        }
        else
        {
            m_selected.clear();
            m_selected.insert(id);
        }
        m_anchor = id;
    }

    bool isSelected(int id) const { return m_selected.count(id) > 0; }
    std::vector<int> selected() const { return { m_selected.begin(), m_selected.end() }; }
    int anchor() const { return m_anchor; }

private:
    std::set<int> m_selected;
    int m_anchor{ -1 };
};

unitTests:
using Ids = std::vector<int>;
const Ids rows{ 10, 20, 30, 40, 50, 60 };
TEST("click") { Selection s; s.click(rows, 30, false, false); CHECK_EQ(s.selected(), (Ids{ 30 })); CHECK_EQ(s.anchor(), 30); s.click(rows, 50, false, false); CHECK_EQ(s.selected(), (Ids{ 50 })); }
TEST("ctrl toggles") { Selection s; s.click(rows, 20, false, false); s.click(rows, 40, true, false); CHECK_EQ(s.selected(), (Ids{ 20, 40 })); s.click(rows, 20, true, false); CHECK_EQ(s.selected(), (Ids{ 40 })); CHECK_EQ(s.anchor(), 20); }
TEST("shift range") { Selection s; s.click(rows, 20, false, false); s.click(rows, 50, false, true); CHECK_EQ(s.selected(), (Ids{ 20, 30, 40, 50 })); CHECK_EQ(s.anchor(), 20); }
TEST("shift again changes the end") { Selection s; s.click(rows, 40, false, false); s.click(rows, 60, false, true); s.click(rows, 10, false, true); CHECK_EQ(s.selected(), (Ids{ 10, 20, 30, 40 })); }
TEST("ctrl shift adds a range") { Selection s; s.click(rows, 10, false, false); s.click(rows, 50, true, false); s.click(rows, 60, true, true); CHECK_EQ(s.selected(), (Ids{ 10, 50, 60 })); }
TEST("display order, not id order") { Selection s; const Ids tree{ 5, 1, 9, 3 }; s.click(tree, 1, false, false); s.click(tree, 3, false, true); CHECK_EQ(s.selected(), (Ids{ 1, 3, 9 })); }
TEST("shift with no anchor") { Selection s; s.click(rows, 30, false, true); CHECK_EQ(s.selected(), (Ids{ 30 })); CHECK_EQ(s.anchor(), 30); }

